describe('GameConfig: Defaults', () => {
  it('binds Tab to the scores, as Q3\'s default config does', () => {
    expect(new GameConfig({ debugMode: true }).binds.entries()).toContainEqual([K.TAB, '+scores']);
  });

  it('binds every key as a fresh config does and sets every setting back, keeping other cvars', () => {
    const config = new GameConfig({
      config: 'seta cg_fov "110"\nbind x "+attack"\nunbind w\nseta r_mode "4"\n',
      warn: () => {}
    });
    config.restoreDefaults();
    expect(config.text()).toBe(
      FRESH.replace(
        'seta pcq_gsplatColorAngle "10"\n',
        'seta pcq_gsplatColorAngle "10"\nseta r_mode "4"\n'
      )
    );
  });

  it("leaves a Debug setting without DEBUG_MODE as the file has it, and sets Graphics' back", () => {
    const config = new GameConfig({
      config: 'seta pcq_god "1"\nseta cg_fov "110"\nseta cl_renderer "opengl2"\n',
      debugMode: false,
      warn: () => {}
    });
    config.restoreDefaults();
    expect(config.text()).toContain('seta pcq_god "1"');
    expect(config.text()).toContain('seta cg_fov "89.2"');
    expect(config.text()).toContain('seta cl_renderer "opengl1"');
    expect(config.text()).not.toContain('bind c ');
  });
});

/** A config as ioq3 writes one: its own binds, cvars the port uses, and some it doesn't. */
const IOQ3_CONFIG = [
  '// generated by ioq3, do not modify',
  'unbindall',
  'bind TAB "+scores"',
  'bind \\ "+mlook"',
  'bind c "+movedown"',
  'bind w "+forward"',
  'bind CTRL "+attack"',
  'bind MWHEELDOWN "weapnext"',
  'seta cg_crosshairrgb "1 1 1 1"',
  'seta cg_fov "115"',
  'seta sensitivity "2"',
  'seta m_pitch "-0.022000"',
  'seta name "^1Unnamed^7Player"',
  'seta cl_renderer "opengl2"'
].join('\r\n');

describe('GameConfig at start', () => {
  it('writes every bind and every setting at its default on a first run', () => {
    expect(new GameConfig({ debugMode: true }).text()).toBe(FRESH);
  });

  it('reads back the file it wrote, to the same file', () => {
    const config = new GameConfig({ debugMode: true });
    config.cvars.set('cg_fov', '100');
    config.binds.set(K.CTRL, '+attack');
    const text = config.text();
    expect(new GameConfig({ config: text, debugMode: true }).text()).toBe(text);
  });

  it("runs a config ioq3 wrote: its binds replace the defaults, and it keeps the cvars it can't use", () => {
    const config = new GameConfig({ config: IOQ3_CONFIG, debugMode: true });
    expect(config.binds.entries()).toEqual([
      [K.TAB, '+scores'],
      [92, '+mlook'],
      [99, '+movedown'],
      [119, '+forward'],
      [K.CTRL, '+attack'],
      [K.MWHEELDOWN, 'weapnext']
    ]);
    expect(config.cvars.settings).toMatchObject({
      fov: 115,
      sensitivity: 2,
      mPitch: -0.022,
      name: '^1Unnamed^7Player',
      renderer: 'opengl2'
    });
    expect(config.text()).toContain('seta cg_crosshairrgb "1 1 1 1"\n');
  });

  it('adds the binds of a file that does not unbind first to the defaults', () => {
    const config = new GameConfig({ config: 'bind CTRL "+attack"\nunbind f', debugMode: true });
    expect(config.binds.get(K.CTRL)).toBe('+attack');
    expect(config.binds.get(119)).toBe('+forward');
    expect(config.binds.get(102)).toBeUndefined();
  });

  it("sets a cvar from a line that is only its name and a value, as Cvar_Command does", () => {
    const config = new GameConfig({ config: 'cg_fov 100\ncg_drawFPS', debugMode: true });
    expect(config.cvars.settings).toMatchObject({ fov: 100, drawFPS: false });
  });

  it('puts the query string over the file, and keeps it out of the file', () => {
    const config = new GameConfig({ config: IOQ3_CONFIG, search: '?cg_fov=100', debugMode: true });
    expect(config.cvars.settings.fov).toBe(100);
    expect(config.text()).toContain('seta cg_fov "115"\n');
  });

  it("reports a line it can't run, and a key Q3 doesn't know", () => {
    const warn = vi.fn();
    new GameConfig({ config: 'vstr go\nbind NOPE +attack', debugMode: true, warn });
    expect(warn.mock.calls.map(([message]) => message)).toEqual([
      'Unknown command "vstr"',
      '"NOPE" isn\'t a valid key'
    ]);
  });
});

describe('GameConfig as it runs', () => {
  it('announces a save for each change to a bind or a setting', () => {
    const config = new GameConfig({ debugMode: true });
    const save = vi.fn();
    config.onSave(save);
    config.command(['bind', 'CTRL', '+attack']);
    config.command(['cg_fov', '100']);
    config.command(['toggle', 'cg_drawFPS']);
    expect(save).toHaveBeenCalledTimes(3);
    expect(config.cvars.settings).toMatchObject({ fov: 100, drawFPS: true });
  });

  it('runs an imported config now, but leaves a latched setting for the next start', () => {
    const config = new GameConfig({ debugMode: true });
    config.exec(IOQ3_CONFIG);
    expect(config.cvars.settings).toMatchObject({ fov: 115, renderer: 'opengl1' });
    expect(config.text()).toContain('seta cl_renderer "opengl2"\n');
    expect(config.binds.get(K.CTRL)).toBe('+attack');
  });

  it('warns of a Ctrl or Meta bind made as it runs, but not of one the file had, nor in the shell', () => {
    const warn = vi.fn();
    const config = new GameConfig({ config: 'bind CTRL "+attack"', debugMode: true, warn });
    expect(warn).not.toHaveBeenCalled();
    config.command(['bind', 'WINDOWS', '+attack']);
    expect(warn).toHaveBeenCalledOnce();
    expect(warn.mock.calls[0][0]).toMatch(/^WINDOWS: /);

    const shell = vi.fn();
    new GameConfig({ debugMode: true, shell: true, warn: shell }).command(['bind', 'CTRL', '+attack']);
    expect(shell).not.toHaveBeenCalled();
  });

  it("does not take a command it doesn't know", () => {
    expect(new GameConfig({ debugMode: true }).command(['weapon', '5'])).toBe(false);
  });
});

describe('GameConfig without DEBUG_MODE', () => {
  it('acts at the Debug defaults, and leaves the file as it was', () => {
    const debugging = new GameConfig({ debugMode: true });
    debugging.command(['pcq_god', '1']);
    debugging.command(['cg_thirdPerson', '1']);
    debugging.command(['cl_renderer', 'opengl2']);
    const text = debugging.text();

    const warn = vi.fn();
    const config = new GameConfig({ config: text, debugMode: false, warn });
    // A server with `sv_cheats` 0 puts the cheat settings back, as a systeminfo does, so the file's
    // `pcq_god 1` and `cg_thirdPerson 1` do not take force. The renderer is no cheat setting, and a
    // written value stands, as it does in Q3.
    config.cvars.set('sv_cheats', '0');
    expect(config.cvars.settings).toEqual({ ...DEFAULT_SETTINGS, renderer: 'opengl2' });
    // C is still bound, as the file has it, but the toggle it runs is refused.
    config.command(['toggle', 'pcq_drawCollision']);
    expect(config.cvars.settings.drawCollision).toBe(false);
    expect(warn).toHaveBeenCalledWith('pcq_drawCollision is cheat protected.');
    // The reset writes its defaults back, as `Cvar_SetCheatState` does.
    expect(config.text()).toContain('seta pcq_god "0"');
    expect(config.text()).toContain('seta cg_thirdPerson "0"');
  });
});
